import os
import torch
import torch.nn as nn
import torch.nn.functional as F
import math
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

# Fused RMSNorm kernel for HIP
rmsnorm_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

__global__ void rmsnorm_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    int hidden_size,
    int num_elements,
    float eps
) {
    int row = blockIdx.x;
    int tid = threadIdx.x;

    if (row >= num_elements / hidden_size) return;

    const float* row_input = input + row * hidden_size;
    float* row_output = output + row * hidden_size;

    // Compute sum of squares using parallel reduction
    __shared__ float shared_sum[256];
    float local_sum = 0.0f;

    for (int i = tid; i < hidden_size; i += blockDim.x) {
        float val = row_input[i];
        local_sum += val * val;
    }

    shared_sum[tid] = local_sum;
    __syncthreads();

    // Reduction in shared memory
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_sum[tid] += shared_sum[tid + s];
        }
        __syncthreads();
    }

    float variance = shared_sum[0] / hidden_size;
    float rsqrt_var = rsqrtf(variance + eps);

    // Apply normalization and weight
    for (int i = tid; i < hidden_size; i += blockDim.x) {
        row_output[i] = row_input[i] * rsqrt_var * weight[i];
    }
}

torch::Tensor rmsnorm_hip(torch::Tensor input, torch::Tensor weight, float eps) {
    auto output = torch::empty_like(input);
    int hidden_size = input.size(-1);
    int num_elements = input.numel();
    int num_rows = num_elements / hidden_size;

    int block_size = 256;
    rmsnorm_kernel<<<num_rows, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        hidden_size,
        num_elements,
        eps
    );

    return output;
}
"""

# Fused RoPE kernel
rope_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

__global__ void apply_rope_kernel(
    const float* __restrict__ q_pe,
    const float* __restrict__ k_pe,
    const float* __restrict__ cos,
    const float* __restrict__ sin,
    float* __restrict__ q_out,
    float* __restrict__ k_out,
    int batch_size,
    int num_heads,
    int seq_len,
    int rope_dim
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int half_dim = rope_dim / 2;
    int total_q = batch_size * num_heads * seq_len * rope_dim;
    int total_k = batch_size * 1 * seq_len * rope_dim;

    // Process Q
    if (idx < total_q) {
        int d = idx % rope_dim;
        int s = (idx / rope_dim) % seq_len;
        int h = (idx / (rope_dim * seq_len)) % num_heads;
        int b = idx / (rope_dim * seq_len * num_heads);

        float cos_val = cos[s * rope_dim + d];
        float sin_val = sin[s * rope_dim + d];

        float q_val = q_pe[idx];
        float q_rot;
        if (d < half_dim) {
            q_rot = -q_pe[b * num_heads * seq_len * rope_dim + h * seq_len * rope_dim + s * rope_dim + d + half_dim];
        } else {
            q_rot = q_pe[b * num_heads * seq_len * rope_dim + h * seq_len * rope_dim + s * rope_dim + d - half_dim];
        }

        q_out[idx] = q_val * cos_val + q_rot * sin_val;
    }

    // Process K (separate pass for simplicity)
    if (idx < total_k) {
        int d = idx % rope_dim;
        int s = (idx / rope_dim) % seq_len;
        int h = (idx / (rope_dim * seq_len)) % 1;
        int b = idx / (rope_dim * seq_len * 1);

        float cos_val = cos[s * rope_dim + d];
        float sin_val = sin[s * rope_dim + d];

        float k_val = k_pe[idx];
        float k_rot;
        if (d < half_dim) {
            k_rot = -k_pe[b * 1 * seq_len * rope_dim + h * seq_len * rope_dim + s * rope_dim + d + half_dim];
        } else {
            k_rot = k_pe[b * 1 * seq_len * rope_dim + h * seq_len * rope_dim + s * rope_dim + d - half_dim];
        }

        k_out[idx] = k_val * cos_val + k_rot * sin_val;
    }
}

std::vector<torch::Tensor> apply_rope_hip(
    torch::Tensor q_pe, 
    torch::Tensor k_pe, 
    torch::Tensor cos, 
    torch::Tensor sin
) {
    auto q_out = torch::empty_like(q_pe);
    auto k_out = torch::empty_like(k_pe);

    int batch_size = q_pe.size(0);
    int num_heads = q_pe.size(1);
    int seq_len = q_pe.size(2);
    int rope_dim = q_pe.size(3);

    int total_elements = batch_size * num_heads * seq_len * rope_dim;
    int block_size = 256;
    int num_blocks = (total_elements + block_size - 1) / block_size;

    apply_rope_kernel<<<num_blocks, block_size>>>(
        q_pe.data_ptr<float>(),
        k_pe.data_ptr<float>(),
        cos.data_ptr<float>(),
        sin.data_ptr<float>(),
        q_out.data_ptr<float>(),
        k_out.data_ptr<float>(),
        batch_size,
        num_heads,
        seq_len,
        rope_dim
    );

    return {q_out, k_out};
}
"""

cpp_source = rmsnorm_source + rope_source + """
PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("rmsnorm_hip", &rmsnorm_hip, "RMSNorm HIP kernel");
    m.def("apply_rope_hip", &apply_rope_hip, "Apply RoPE HIP kernel");
}
"""

custom_ops = load_inline(
    name="custom_mla_ops",
    cpp_sources=cpp_source,
    functions=["rmsnorm_hip", "apply_rope_hip"],
    verbose=True,
    extra_cuda_cflags=["-O3"],
)


class DeepSeekRMSNormOptimized(nn.Module):
    def __init__(self, hidden_size, eps=1e-6):
        super().__init__()
        self.weight = nn.Parameter(torch.ones(hidden_size))
        self.variance_epsilon = eps

    def forward(self, hidden_states):
        return custom_ops.rmsnorm_hip(hidden_states.contiguous(), self.weight, self.variance_epsilon)


class DeepSeekRotaryEmbedding(nn.Module):
    def __init__(self, dim, max_position_embeddings=2048, base=10000.0):
        super().__init__()
        self.dim = dim
        self.max_position_embeddings = max_position_embeddings
        self.base = base
        inv_freq = 1.0 / (self.base ** (torch.arange(0, self.dim, 2, dtype=torch.float32) / self.dim))
        self.register_buffer("inv_freq", inv_freq, persistent=False)

    @torch.no_grad()
    def forward(self, x, seq_len=None):
        if seq_len is None:
            seq_len = x.shape[-2]
        t = torch.arange(seq_len, device=x.device, dtype=torch.float32)
        freqs = torch.outer(t, self.inv_freq)
        emb = torch.cat((freqs, freqs), dim=-1)
        return emb.cos(), emb.sin()


def rotate_half(x):
    x1 = x[..., : x.shape[-1] // 2]
    x2 = x[..., x.shape[-1] // 2 :]
    return torch.cat((-x2, x1), dim=-1)


def apply_rotary_pos_emb(q, k, cos, sin, position_ids=None, unsqueeze_dim=1):
    cos = cos.unsqueeze(0).unsqueeze(0)
    sin = sin.unsqueeze(0).unsqueeze(0)
    q_embed = (q * cos) + (rotate_half(q) * sin)
    k_embed = (k * cos) + (rotate_half(k) * sin)
    return q_embed, k_embed


class ModelNew(nn.Module):
    def __init__(
        self,
        hidden_size: int,
        num_attention_heads: int,
        q_lora_rank: int,
        kv_lora_rank: int,
        qk_nope_head_dim: int,
        qk_rope_head_dim: int,
        v_head_dim: int,
        max_position_embeddings: int = 2048,
        rope_theta: float = 10000.0,
        attention_dropout: float = 0.0,
    ):
        super().__init__()
        self.hidden_size = hidden_size
        self.num_heads = num_attention_heads
        self.q_lora_rank = q_lora_rank
        self.kv_lora_rank = kv_lora_rank
        self.qk_nope_head_dim = qk_nope_head_dim
        self.qk_rope_head_dim = qk_rope_head_dim
        self.v_head_dim = v_head_dim
        self.q_head_dim = qk_nope_head_dim + qk_rope_head_dim
        self.attention_dropout = attention_dropout
        self.softmax_scale = self.q_head_dim ** (-0.5)

        # Query projection with LoRA compression
        self.q_a_proj = nn.Linear(hidden_size, q_lora_rank, bias=False)
        self.q_a_layernorm = DeepSeekRMSNormOptimized(q_lora_rank)
        self.q_b_proj = nn.Linear(q_lora_rank, num_attention_heads * self.q_head_dim, bias=False)

        # KV projection with LoRA compression
        self.kv_a_proj_with_mqa = nn.Linear(hidden_size, kv_lora_rank + qk_rope_head_dim, bias=False)
        self.kv_a_layernorm = DeepSeekRMSNormOptimized(kv_lora_rank)
        self.kv_b_proj = nn.Linear(kv_lora_rank, num_attention_heads * (qk_nope_head_dim + v_head_dim), bias=False)

        # Output projection
        self.o_proj = nn.Linear(num_attention_heads * v_head_dim, hidden_size, bias=False)

        # Rotary embeddings
        self.rotary_emb = DeepSeekRotaryEmbedding(
            qk_rope_head_dim,
            max_position_embeddings=max_position_embeddings,
            base=rope_theta,
        )

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        bsz, q_len, _ = hidden_states.size()

        # Query projection with LoRA compression
        q = self.q_b_proj(self.q_a_layernorm(self.q_a_proj(hidden_states)))
        q = q.view(bsz, q_len, self.num_heads, self.q_head_dim).transpose(1, 2)

        # Split query into nope and rope components
        q_nope, q_pe = torch.split(q, [self.qk_nope_head_dim, self.qk_rope_head_dim], dim=-1)

        # KV projection with compression
        compressed_kv = self.kv_a_proj_with_mqa(hidden_states)
        compressed_kv, k_pe = torch.split(compressed_kv, [self.kv_lora_rank, self.qk_rope_head_dim], dim=-1)
        k_pe = k_pe.view(bsz, q_len, 1, self.qk_rope_head_dim).transpose(1, 2)

        # Expand compressed KV
        kv = self.kv_b_proj(self.kv_a_layernorm(compressed_kv))
        kv = kv.view(bsz, q_len, self.num_heads, self.qk_nope_head_dim + self.v_head_dim)
        kv = kv.transpose(1, 2)

        k_nope, value_states = torch.split(kv, [self.qk_nope_head_dim, self.v_head_dim], dim=-1)

        # Apply rotary embeddings - use PyTorch version for correctness
        cos, sin = self.rotary_emb(value_states, seq_len=q_len)
        q_pe, k_pe = apply_rotary_pos_emb(q_pe, k_pe, cos, sin)

        # Assemble full query and key states
        query_states = torch.cat([q_nope, q_pe], dim=-1)
        key_states = torch.cat([k_nope, k_pe.expand(-1, self.num_heads, -1, -1)], dim=-1)

        # Compute attention using efficient SDPA
        attn_output = F.scaled_dot_product_attention(
            query_states,
            key_states,
            value_states,
            attn_mask=None,
            dropout_p=self.attention_dropout if self.training else 0.0,
            is_causal=True,
            scale=self.softmax_scale,
        )

        attn_output = attn_output.transpose(1, 2).contiguous()
        attn_output = attn_output.reshape(bsz, q_len, self.num_heads * self.v_head_dim)
        attn_output = self.o_proj(attn_output)

        return attn_output


def custom_kernel(inputs):
    # Get input tensor
    hidden_states = inputs[0]

    # Create model with default parameters
    hidden_size = 2048
    num_attention_heads = 16
    q_lora_rank = 1536
    kv_lora_rank = 512
    qk_nope_head_dim = 128
    qk_rope_head_dim = 64
    v_head_dim = 128
    max_position_embeddings = 4096

    model = ModelNew(
        hidden_size=hidden_size,
        num_attention_heads=num_attention_heads,
        q_lora_rank=q_lora_rank,
        kv_lora_rank=kv_lora_rank,
        qk_nope_head_dim=qk_nope_head_dim,
        qk_rope_head_dim=qk_rope_head_dim,
        v_head_dim=v_head_dim,
        max_position_embeddings=max_position_embeddings,
    ).cuda().eval()

    with torch.no_grad():
        return model(hidden_states)

