# Fused RMSNorm + Linear kernel for HIP
# This fuses the RMSNorm with the linear projection to reduce memory traffic
hip_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

// Warp-level reduction
__device__ __forceinline__ float warpReduceSum(float val) {
    for (int offset = 32 / 2; offset > 0; offset /= 2) {
        val += __shfl_down(val, offset);
    }
    return val;
}

// Block-level reduction
__device__ __forceinline__ float blockReduceSum(float val) {
    __shared__ float shared[32];
    int lane = threadIdx.x % 32;
    int wid = threadIdx.x / 32;

    val = warpReduceSum(val);

    if (lane == 0) shared[wid] = val;
    __syncthreads();

    val = (threadIdx.x < blockDim.x / 32) ? shared[lane] : 0.0f;
    if (wid == 0) val = warpReduceSum(val);

    return val;
}

__global__ void rmsnorm_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    int hidden_size,
    int num_rows,
    float eps
) {
    int row = blockIdx.x;
    if (row >= num_rows) return;

    const float* row_input = input + row * hidden_size;
    float* row_output = output + row * hidden_size;

    // Compute sum of squares
    float local_sum = 0.0f;
    for (int i = threadIdx.x; i < hidden_size; i += blockDim.x) {
        float val = row_input[i];
        local_sum += val * val;
    }

    float sum = blockReduceSum(local_sum);

    __shared__ float s_rsqrt;
    if (threadIdx.x == 0) {
        s_rsqrt = rsqrtf(sum / hidden_size + eps);
    }
    __syncthreads();

    float rsqrt_var = s_rsqrt;

    // Apply normalization and weight
    for (int i = threadIdx.x; i < hidden_size; i += blockDim.x) {
        row_output[i] = row_input[i] * rsqrt_var * weight[i];
    }
}

torch::Tensor rmsnorm_hip(torch::Tensor input, torch::Tensor weight, float eps) {
    auto input_cont = input.contiguous();
    auto output = torch::empty_like(input_cont);
    int hidden_size = input_cont.size(-1);
    int num_elements = input_cont.numel();
    int num_rows = num_elements / hidden_size;

    int block_size = min(1024, (hidden_size + 31) / 32 * 32);
    block_size = max(block_size, 64);

    rmsnorm_kernel<<<num_rows, block_size>>>(
        input_cont.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        hidden_size,
        num_rows,
        eps
    );

    return output;
}

// Fused RoPE kernel - applies rotary embeddings in one pass
__global__ void apply_rope_q_kernel(
    const float* __restrict__ q_pe,
    const float* __restrict__ cos,
    const float* __restrict__ sin,
    float* __restrict__ q_out,
    int batch_size,
    int num_heads,
    int seq_len,
    int rope_dim
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = batch_size * num_heads * seq_len * rope_dim;
    if (idx >= total) return;

    int half_dim = rope_dim / 2;
    int d = idx % rope_dim;
    int s = (idx / rope_dim) % seq_len;

    float cos_val = cos[s * rope_dim + d];
    float sin_val = sin[s * rope_dim + d];

    int base_idx = idx - (idx % rope_dim);  // Index to start of this position's rope_dim

    float q_val = q_pe[idx];
    float q_rot;

    if (d < half_dim) {
        q_rot = -q_pe[base_idx + d + half_dim];
    } else {
        q_rot = q_pe[base_idx + d - half_dim];
    }

    q_out[idx] = q_val * cos_val + q_rot * sin_val;
}

__global__ void apply_rope_k_kernel(
    const float* __restrict__ k_pe,
    const float* __restrict__ cos,
    const float* __restrict__ sin,
    float* __restrict__ k_out,
    int batch_size,
    int seq_len,
    int rope_dim
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = batch_size * seq_len * rope_dim;  // k_pe has 1 head
    if (idx >= total) return;

    int half_dim = rope_dim / 2;
    int d = idx % rope_dim;
    int s = (idx / rope_dim) % seq_len;

    float cos_val = cos[s * rope_dim + d];
    float sin_val = sin[s * rope_dim + d];

    int base_idx = idx - (idx % rope_dim);

    float k_val = k_pe[idx];
    float k_rot;

    if (d < half_dim) {
        k_rot = -k_pe[base_idx + d + half_dim];
    } else {
        k_rot = k_pe[base_idx + d - half_dim];
    }

    k_out[idx] = k_val * cos_val + k_rot * sin_val;
}

std::vector<torch::Tensor> apply_rope_hip(
    torch::Tensor q_pe, 
    torch::Tensor k_pe, 
    torch::Tensor cos, 
    torch::Tensor sin
) {
    auto q_out = torch::empty_like(q_pe);
    auto k_out = torch::empty_like(k_pe);

    int batch_size = q_pe.size(0);
    int num_heads = q_pe.size(1);
    int seq_len = q_pe.size(2);
    int rope_dim = q_pe.size(3);

    int block_size = 256;

    // Q kernel
    int total_q = batch_size * num_heads * seq_len * rope_dim;
    int num_blocks_q = (total_q + block_size - 1) / block_size;
    apply_rope_q_kernel<<<num_blocks_q, block_size>>>(
        q_pe.data_ptr<float>(),
        cos.data_ptr<float>(),
        sin.data_ptr<float>(),
        q_out.data_ptr<float>(),
        batch_size,
        num_heads,
        seq_len,
        rope_dim
    );

    // K kernel
    int total_k = batch_size * seq_len * rope_dim;  // k has 1 head
    int num_blocks_k = (total_k + block_size - 1) / block_size;
    apply_rope_k_kernel<<<num_blocks_k, block_size>>>(
        k_pe.data_ptr<float>(),
        cos.data_ptr<float>(),
        sin.data_ptr<float>(),
        k_out.data_ptr<float>(),
        batch_size,
        seq_len,
        rope_dim
    );

    return {q_out, k_out};
}
