# Fused RMSNorm kernel for HIP
rmsnorm_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

__global__ void rmsnorm_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    int hidden_size,
    int num_elements,
    float eps
) {
    int row = blockIdx.x;
    int tid = threadIdx.x;

    if (row >= num_elements / hidden_size) return;

    const float* row_input = input + row * hidden_size;
    float* row_output = output + row * hidden_size;

    // Compute sum of squares using parallel reduction
    __shared__ float shared_sum[256];
    float local_sum = 0.0f;

    for (int i = tid; i < hidden_size; i += blockDim.x) {
        float val = row_input[i];
        local_sum += val * val;
    }

    shared_sum[tid] = local_sum;
    __syncthreads();

    // Reduction in shared memory
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_sum[tid] += shared_sum[tid + s];
        }
        __syncthreads();
    }

    float variance = shared_sum[0] / hidden_size;
    float rsqrt_var = rsqrtf(variance + eps);

    // Apply normalization and weight
    for (int i = tid; i < hidden_size; i += blockDim.x) {
        row_output[i] = row_input[i] * rsqrt_var * weight[i];
    }
}

torch::Tensor rmsnorm_hip(torch::Tensor input, torch::Tensor weight, float eps) {
    auto output = torch::empty_like(input);
    int hidden_size = input.size(-1);
    int num_elements = input.numel();
    int num_rows = num_elements / hidden_size;

    int block_size = 256;
    rmsnorm_kernel<<<num_rows, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        hidden_size,
        num_elements,
        eps
    );

    return output;
}
"""

# Fused RoPE kernel
rope_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

__global__ void apply_rope_kernel(
    const float* __restrict__ q_pe,
    const float* __restrict__ k_pe,
    const float* __restrict__ cos,
    const float* __restrict__ sin,
    float* __restrict__ q_out,
    float* __restrict__ k_out,
    int batch_size,
    int num_heads,
    int seq_len,
    int rope_dim
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int half_dim = rope_dim / 2;
    int total_q = batch_size * num_heads * seq_len * rope_dim;
    int total_k = batch_size * 1 * seq_len * rope_dim;

    // Process Q
    if (idx < total_q) {
        int d = idx % rope_dim;
        int s = (idx / rope_dim) % seq_len;
        int h = (idx / (rope_dim * seq_len)) % num_heads;
        int b = idx / (rope_dim * seq_len * num_heads);

        float cos_val = cos[s * rope_dim + d];
        float sin_val = sin[s * rope_dim + d];

        float q_val = q_pe[idx];
        float q_rot;
        if (d < half_dim) {
            q_rot = -q_pe[b * num_heads * seq_len * rope_dim + h * seq_len * rope_dim + s * rope_dim + d + half_dim];
        } else {
            q_rot = q_pe[b * num_heads * seq_len * rope_dim + h * seq_len * rope_dim + s * rope_dim + d - half_dim];
        }

        q_out[idx] = q_val * cos_val + q_rot * sin_val;
    }

    // Process K (separate pass for simplicity)
    if (idx < total_k) {
        int d = idx % rope_dim;
        int s = (idx / rope_dim) % seq_len;
        int h = (idx / (rope_dim * seq_len)) % 1;
        int b = idx / (rope_dim * seq_len * 1);

        float cos_val = cos[s * rope_dim + d];
        float sin_val = sin[s * rope_dim + d];

        float k_val = k_pe[idx];
        float k_rot;
        if (d < half_dim) {
            k_rot = -k_pe[b * 1 * seq_len * rope_dim + h * seq_len * rope_dim + s * rope_dim + d + half_dim];
        } else {
            k_rot = k_pe[b * 1 * seq_len * rope_dim + h * seq_len * rope_dim + s * rope_dim + d - half_dim];
        }

        k_out[idx] = k_val * cos_val + k_rot * sin_val;
    }
}

std::vector<torch::Tensor> apply_rope_hip(
    torch::Tensor q_pe, 
    torch::Tensor k_pe, 
    torch::Tensor cos, 
    torch::Tensor sin
) {
    auto q_out = torch::empty_like(q_pe);
    auto k_out = torch::empty_like(k_pe);

    int batch_size = q_pe.size(0);
    int num_heads = q_pe.size(1);
    int seq_len = q_pe.size(2);
    int rope_dim = q_pe.size(3);

    int total_elements = batch_size * num_heads * seq_len * rope_dim;
    int block_size = 256;
    int num_blocks = (total_elements + block_size - 1) / block_size;

    apply_rope_kernel<<<num_blocks, block_size>>>(
        q_pe.data_ptr<float>(),
        k_pe.data_ptr<float>(),
        cos.data_ptr<float>(),
        sin.data_ptr<float>(),
        q_out.data_ptr<float>(),
        k_out.data_ptr<float>(),
        batch_size,
        num_heads,
        seq_len,
        rope_dim
    );

    return {q_out, k_out};
}
"""

cpp_source = rmsnorm_source + rope_source + """
PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
